-- Central government schemes for farmers, fish farmers and livestock owners.
-- Details are as known in June 2026; the app shows this date and always links to the official site.
-- State schemes are not listed because their names and amounts change often; add them here once verified.
insert into public.schemes (code, level, sectors, name, summary, rules, official_url, info_as_of) values
('pm_kisan', 'central', '{agriculture}',
 '{"en":"PM-KISAN","te":"పీఎం-కిసాన్","hi":"पीएम-किसान"}',
 '{"en":"₹6,000 a year income support to land-holding farmer families, paid in three instalments of ₹2,000 to the bank account. Income-tax payers, government employees and institutional landholders are excluded.","te":"భూమి ఉన్న రైతు కుటుంబాలకు సంవత్సరానికి ₹6,000 ఆదాయ సహాయం, ₹2,000 చొప్పున మూడు విడతలుగా బ్యాంక్ ఖాతాలో జమ. ఆదాయపు పన్ను చెల్లించేవారు, ప్రభుత్వ ఉద్యోగులు, సంస్థాగత భూయజమానులు అర్హులు కారు.","hi":"भूमिधारक किसान परिवारों को सालाना ₹6,000 की आय सहायता, ₹2,000 की तीन किस्तों में बैंक खाते में। आयकर दाता, सरकारी कर्मचारी और संस्थागत भूमिधारक पात्र नहीं हैं।"}',
 '{"requires_land":true}', 'https://pmkisan.gov.in', '2026-06-01'),
('pmfby', 'central', '{agriculture}',
 '{"en":"Pradhan Mantri Fasal Bima Yojana (crop insurance)","te":"ప్రధానమంత్రి ఫసల్ బీమా యోజన (పంట బీమా)","hi":"प्रधानमंत्री फसल बीमा योजना (फसल बीमा)"}',
 '{"en":"Insurance against crop loss from natural calamities, pests and disease. Farmer premium is capped at 2% for kharif, 1.5% for rabi food and oilseed crops and 5% for commercial/horticulture crops. Enrol through your bank, CSC or the portal before the season cut-off date.","te":"ప్రకృతి వైపరీత్యాలు, పురుగులు, వ్యాధుల వల్ల పంట నష్టానికి బీమా. రైతు ప్రీమియం ఖరీఫ్‌కు 2%, రబీ ఆహార, నూనెగింజల పంటలకు 1.5%, వాణిజ్య/ఉద్యాన పంటలకు 5% మాత్రమే. సీజన్ గడువు లోపు బ్యాంక్, CSC లేదా పోర్టల్ ద్వారా నమోదు చేసుకోండి.","hi":"प्राकृतिक आपदा, कीट और रोग से फसल नुकसान का बीमा। किसान का प्रीमियम खरीफ़ में 2%, रबी खाद्य व तिलहन फसलों में 1.5% और वाणिज्यिक/बागवानी फसलों में 5% तक। सीज़न की अंतिम तिथि से पहले बैंक, CSC या पोर्टल से नामांकन करें।"}',
 '{"crop_required":true}', 'https://pmfby.gov.in', '2026-06-01'),
('kcc', 'central', '{agriculture,aquaculture,livestock}',
 '{"en":"Kisan Credit Card (KCC)","te":"కిసాన్ క్రెడిట్ కార్డ్ (KCC)","hi":"किसान क्रेडिट कार्ड (KCC)"}',
 '{"en":"Short-term bank credit for crops, fisheries and animal husbandry at a subsidised interest rate; paying back on time earns an extra interest reduction. Apply at any bank branch.","te":"పంటలు, మత్స్య, పశుపోషణ కోసం తక్కువ వడ్డీకి స్వల్పకాలిక బ్యాంక్ రుణం; సమయానికి తిరిగి చెల్లిస్తే అదనపు వడ్డీ తగ్గింపు. ఏ బ్యాంక్ శాఖలోనైనా దరఖాస్తు చేయవచ్చు.","hi":"फसल, मत्स्य पालन और पशुपालन के लिए रियायती ब्याज पर अल्पकालीन बैंक ऋण; समय पर चुकाने पर अतिरिक्त ब्याज छूट। किसी भी बैंक शाखा में आवेदन करें।"}',
 '{}', 'https://www.myscheme.gov.in/schemes/kcc', '2026-06-01'),
('soil_health_card', 'central', '{agriculture}',
 '{"en":"Soil Health Card","te":"సాయిల్ హెల్త్ కార్డ్","hi":"मृदा स्वास्थ्य कार्ड"}',
 '{"en":"Free soil testing with a card showing nutrient status and fertiliser recommendations for your field. Contact your agriculture officer or soil testing lab.","te":"ఉచిత మట్టి పరీక్ష, మీ పొలానికి పోషకాల స్థితి మరియు ఎరువుల సిఫార్సులతో కార్డ్. మీ వ్యవసాయ అధికారి లేదా మట్టి పరీక్ష ప్రయోగశాలను సంప్రదించండి.","hi":"मुफ़्त मिट्टी जाँच और आपके खेत के पोषक तत्व व उर्वरक सिफ़ारिशों वाला कार्ड। अपने कृषि अधिकारी या मृदा परीक्षण प्रयोगशाला से संपर्क करें।"}',
 '{"requires_land":true}', 'https://soilhealth.dac.gov.in', '2026-06-01'),
('pmksy_pdmc', 'central', '{agriculture}',
 '{"en":"PMKSY – Per Drop More Crop (micro-irrigation)","te":"PMKSY – పర్ డ్రాప్ మోర్ క్రాప్ (సూక్ష్మ నీటిపారుదల)","hi":"PMKSY – पर ड्रॉप मोर क्रॉप (सूक्ष्म सिंचाई)"}',
 '{"en":"Subsidy for drip and sprinkler irrigation — higher for small and marginal farmers. Apply through the state horticulture/agriculture or micro-irrigation department.","te":"డ్రిప్, స్ప్రింక్లర్ నీటిపారుదలకు సబ్సిడీ — చిన్న, సన్నకారు రైతులకు ఎక్కువ. రాష్ట్ర ఉద్యాన/వ్యవసాయ లేదా సూక్ష్మ నీటిపారుదల శాఖ ద్వారా దరఖాస్తు చేయండి.","hi":"ड्रिप और स्प्रिंकलर सिंचाई पर सब्सिडी — छोटे व सीमांत किसानों के लिए अधिक। राज्य बागवानी/कृषि या सूक्ष्म सिंचाई विभाग से आवेदन करें।"}',
 '{"requires_land":true}', 'https://pmksy.gov.in', '2026-06-01'),
('pm_kusum', 'central', '{agriculture}',
 '{"en":"PM-KUSUM (solar pumps)","te":"పీఎం-కుసుమ్ (సోలార్ పంపులు)","hi":"पीएम-कुसुम (सौर पंप)"}',
 '{"en":"Central and state subsidy for standalone solar irrigation pumps and for solarising grid-connected pumps; the farmer pays the remaining share. Apply through the state renewable energy agency.","te":"స్వతంత్ర సోలార్ నీటిపారుదల పంపులకు మరియు గ్రిడ్ పంపులను సోలార్‌గా మార్చడానికి కేంద్ర, రాష్ట్ర సబ్సిడీ; మిగిలిన వాటా రైతు చెల్లిస్తారు. రాష్ట్ర పునరుత్పాదక ఇంధన సంస్థ ద్వారా దరఖాస్తు చేయండి.","hi":"स्वतंत्र सौर सिंचाई पंप और ग्रिड पंपों के सौरीकरण के लिए केंद्र व राज्य सब्सिडी; बाकी हिस्सा किसान देता है। राज्य नवीकरणीय ऊर्जा एजेंसी से आवेदन करें।"}',
 '{"requires_land":true}', 'https://pmkusum.mnre.gov.in', '2026-06-01'),
('aif', 'central', '{agriculture,aquaculture,livestock}',
 '{"en":"Agriculture Infrastructure Fund","te":"వ్యవసాయ మౌలిక సదుపాయాల నిధి","hi":"कृषि अवसंरचना कोष"}',
 '{"en":"Interest subvention and credit guarantee on loans for post-harvest infrastructure such as storage, cold chains, sorting and processing units.","te":"నిల్వ గోదాములు, శీతల గిడ్డంగులు, గ్రేడింగ్, ప్రాసెసింగ్ వంటి పంట అనంతర మౌలిక సదుపాయాల రుణాలపై వడ్డీ రాయితీ మరియు రుణ హామీ.","hi":"भंडारण, कोल्ड चेन, छँटाई और प्रसंस्करण जैसी फसलोपरांत अवसंरचना के ऋण पर ब्याज छूट और ऋण गारंटी।"}',
 '{}', 'https://agriinfra.dac.gov.in', '2026-06-01'),
('pmmsy', 'central', '{aquaculture}',
 '{"en":"Pradhan Mantri Matsya Sampada Yojana (fisheries)","te":"ప్రధానమంత్రి మత్స్య సంపద యోజన (మత్స్య)","hi":"प्रधानमंत्री मत्स्य संपदा योजना (मत्स्य पालन)"}',
 '{"en":"Financial assistance for new ponds, inputs, aeration, RAS/biofloc units and fish transport — a higher share of the unit cost for women and SC/ST beneficiaries. Apply through the district fisheries office.","te":"కొత్త చెరువులు, ఇన్‌పుట్‌లు, ఏరేషన్, RAS/బయోఫ్లాక్ యూనిట్లు, చేపల రవాణాకు ఆర్థిక సహాయం — మహిళలు, SC/ST లబ్ధిదారులకు యూనిట్ వ్యయంలో ఎక్కువ వాటా. జిల్లా మత్స్య కార్యాలయం ద్వారా దరఖాస్తు చేయండి.","hi":"नए तालाब, इनपुट, एरेशन, RAS/बायोफ्लॉक इकाइयों और मछली परिवहन के लिए वित्तीय सहायता — महिलाओं और SC/ST लाभार्थियों को इकाई लागत का अधिक हिस्सा। ज़िला मत्स्य कार्यालय से आवेदन करें।"}',
 '{}', 'https://pmmsy.dof.gov.in', '2026-06-01'),
('nlm', 'central', '{livestock}',
 '{"en":"National Livestock Mission","te":"జాతీయ పశుసంపద మిషన్","hi":"राष्ट्रीय पशुधन मिशन"}',
 '{"en":"Capital subsidy for starting poultry, sheep, goat, pig and fodder enterprises, plus livestock insurance support. Apply online with a project report.","te":"కోళ్లు, గొర్రెలు, మేకలు, పందులు, పశుగ్రాసం వ్యాపారాలు ప్రారంభించడానికి మూలధన సబ్సిడీ, పశు బీమా సహాయం. ప్రాజెక్ట్ నివేదికతో ఆన్‌లైన్‌లో దరఖాస్తు చేయండి.","hi":"मुर्गी, भेड़, बकरी, सूअर और चारा उद्यम शुरू करने के लिए पूँजी सब्सिडी और पशुधन बीमा सहायता। परियोजना रिपोर्ट के साथ ऑनलाइन आवेदन करें।"}',
 '{}', 'https://nlm.udyamimitra.in', '2026-06-01'),
('rgm', 'central', '{livestock}',
 '{"en":"Rashtriya Gokul Mission","te":"రాష్ట్రీయ గోకుల్ మిషన్","hi":"राष्ट्रीय गोकुल मिशन"}',
 '{"en":"Development of indigenous cattle and buffalo breeds: artificial insemination at the doorstep, sex-sorted semen and breed improvement. Contact your veterinary dispensary.","te":"దేశీ ఆవులు, గేదెల జాతుల అభివృద్ధి: ఇంటి వద్దే కృత్రిమ గర్భధారణ, సెక్స్-సార్టెడ్ వీర్యం, జాతి మెరుగుదల. మీ పశువైద్యశాలను సంప్రదించండి.","hi":"देशी गाय और भैंस नस्लों का विकास: घर पर कृत्रिम गर्भाधान, सेक्स-सॉर्टेड वीर्य और नस्ल सुधार। अपने पशु चिकित्सालय से संपर्क करें।"}',
 '{"species":["cow","buffalo"]}', 'https://dahd.gov.in', '2026-06-01');
